<?php
namespace App\Services;
use App\Models\SacramentalRecord;
class SacramentalRecordValidator {
 public function fields(array $r): array { $map=['sacrament'=>'sacrament_type','firstName'=>'first_name','middleName'=>'middle_name','lastName'=>'last_name','gender'=>'gender','dob'=>'date_of_birth','eventDate'=>'event_date','fatherName'=>'father_name','motherName'=>'mother_maiden_name','spouse'=>'spouse_name','book'=>'book_number','page'=>'page_number','line'=>'line_number','minister'=>'minister_name','sponsors'=>'sponsors','marginNotes'=>'margin_notes'];$o=[];foreach($map as $a=>$b)$o[$b]=trim(strip_tags((string)($r[$a]??$r[$b]??'')));return $o; }
 public function validate(array $r,bool $database=true): array { $f=$this->fields($r);$e=[];$types=['Baptism','Communion','Confirmation','Marriage','Death'];if(!in_array($f['sacrament_type'],$types,true))$e[]='Missing Sacrament Type';if(!$f['first_name']||!$f['last_name'])$e[]='First and last name required';if(!in_array($f['gender'],['Male','Female'],true))$e[]='Gender must be Male or Female';foreach(['event_date','book_number','page_number','line_number'] as $x)if(!$f[$x])$e[]="$x is required";foreach(['date_of_birth','event_date'] as $x)if($f[$x]&&!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$f[$x]))$e[]='Invalid Date';if($f['date_of_birth']&&$f['event_date']&&$f['event_date']<$f['date_of_birth'])$e[]='Invalid Date';if(in_array($f['sacrament_type'],['Baptism','Communion','Confirmation'],true)){if(!$f['father_name'])$e[]='Missing Father Name';if(!$f['mother_maiden_name'])$e[]='Missing Mother Name';}if($database&&!$e&&SacramentalRecord::where('sacrament_type',$f['sacrament_type'])->where('book_number',$f['book_number'])->where('page_number',$f['page_number'])->where('line_number',$f['line_number'])->exists())$e[]='Duplicate Entry';return [$f,array_values(array_unique($e))]; }
}
